  fbStripe.position.set(0, 1.24, -5)
  add(fbStripe)
  const fbStripe2 = new THREE.Mesh(new THREE.BoxGeometry(10.1, 0.06, 8.1), painted.cream)
  fbStripe2.position.set(0, 1.16, -5)
