  // flat rail
  rails.push({ ax: 7.5, az: 4.5, bx: 7.5, bz: 19.5, y: 0.6, kind: 'rail', name: 'FLAT BAR' })
  {
    const rail = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 15, 8), metal)
