/* ------------------------------------------------------------------ *
 *  THRASH PARK — 2 minute trick run
 * ------------------------------------------------------------------ */

const $ = id => document.getElementById(id)
const canvas = $('gl')
const isCoarse = window.matchMedia('(hover: none) and (pointer: coarse)').matches

const ui = {
  hud: $('hud'),
