for (let i=0;i<5;i++) {
  const t=Date.now()
  try { await btn.click({trial:true, timeout:4000}); console.log('trial ok at', Date.now()-t0, 'took', Date.now()-t) }
  catch(e){ console.log('trial fail at', Date.now()-t0, 'took', Date.now()-t, e.name, e.message.split('\n')[0]) }
  await page.waitForTimeout(300)
}
console.log('ready', await page.evaluate(()=>window.__ready), 'loader', await page.evaluate(()=>!!document.getElementById('loader')))
await browser.close()
